// ── Feature Flags ────────────────────────────────────────────────
const ENABLE_EDA = false; // Set to true to enable EDA functionality

// When true, ignore the model/reasoning_effort picked in the UI and force
// the values below for every request. The UI dropdowns remain fully functional
// for future use — flip this flag to false to restore UI-driven selection.
const FORCE_MODEL_OVERRIDE = true;
const FORCED_MODEL = 'gpt-6-luna';
const FORCED_REASONING_EFFORT = 'low';

// When false, the app accepts GIBD keys only (gibd-...). The backend also
// enforces this (utils/agm_helper.ALLOW_OPENAI) — set BOTH this flag and the
// backend ALLOW_OPENAI to true to re-enable OpenAI.
const ALLOW_OPENAI_KEY = true;

// Purge a stale non-GIBD key left in storage from before GIBD-only mode, so it
// isn't sent and rejected by the backend on every request. The user simply
// re-enters their GIBD key.
(function purgeNonGibdStoredKey() {
    if (ALLOW_OPENAI_KEY) return;
    try {
        const k = (localStorage.getItem('agm_openai_api_key') || '').trim();
        if (k && !/^gibd[-_]/i.test(k)) {
            localStorage.removeItem('agm_openai_api_key');
            const el = document.getElementById('GIBD-API-key');
            if (el) el.value = '';
            console.warn('[Auth] Removed a stored non-GIBD key (GIBD-only mode). Enter your GIBD key in Settings.');
        }
    } catch (_) {}
})();

// ── Data-source API keys (Census, EPA AQS, etc.) ─────────────────
// Collected just-in-time in the source-select prompt and remembered here so
// the user only enters each one once. Sent to the backend with download
// requests; the backend overlays them onto the data-source handbooks.
const DATA_SOURCE_KEYS_LS = 'agm_datasource_keys';

function getSavedDataSourceKeys() {
    try {
        return JSON.parse(localStorage.getItem(DATA_SOURCE_KEYS_LS) || '{}') || {};
    } catch (_) {
        return {};
    }
}

function saveDataSourceKeys(map) {
    if (!map) return;
    const cur = getSavedDataSourceKeys();
    let changed = false;
    for (const [k, v] of Object.entries(map)) {
        if (v && cur[k] !== v) { cur[k] = v; changed = true; }
    }
    if (changed) localStorage.setItem(DATA_SOURCE_KEYS_LS, JSON.stringify(cur));
}

function removeSavedDataSourceKey(name) {
    const cur = getSavedDataSourceKeys();
    if (name in cur) {
        delete cur[name];
        localStorage.setItem(DATA_SOURCE_KEYS_LS, JSON.stringify(cur));
    }
}

// Render the saved data-source keys list in Settings (name + masked value +
// remove). Called when the Settings dropdown opens.
function renderDataSourceKeysSettings() {
    const list = document.getElementById('data-source-keys-list');
    if (!list) return;
    const keys = getSavedDataSourceKeys();
    const names = Object.keys(keys);
    list.innerHTML = '';
    if (!names.length) {
        const empty = document.createElement('div');
        empty.style.cssText = 'font-size:12px; color:#999; font-style:italic;';
        empty.textContent = 'No data-source keys saved yet.';
        list.appendChild(empty);
        return;
    }
    names.forEach(name => {
        const val = String(keys[name] || '');
        const masked = val.length > 4 ? '•••• ' + val.slice(-4) : '••••';
        const row = document.createElement('div');
        row.style.cssText = 'display:flex; gap:8px; align-items:center; padding:4px 0; border-bottom:1px solid #eee;';
        const nameEl = document.createElement('span');
        nameEl.style.cssText = 'flex:1; font-size:12px; color:#333; word-break:break-all;';
        nameEl.textContent = name;
        const valEl = document.createElement('span');
        valEl.style.cssText = 'font-size:12px; color:#888; font-family:monospace;';
        valEl.textContent = masked;
        const rm = document.createElement('button');
        rm.textContent = '×';
        rm.title = 'Remove key';
        rm.style.cssText = 'border:1px solid #ccc; background:none; border-radius:4px; cursor:pointer; padding:0 8px; color:#a31b1b;';
        rm.onclick = () => { removeSavedDataSourceKey(name); renderDataSourceKeysSettings(); };
        row.appendChild(nameEl);
        row.appendChild(valEl);
        row.appendChild(rm);
        list.appendChild(row);
    });
}

function addDataSourceKeyFromSettings() {
    const nameEl = document.getElementById('ds-key-new-name');
    const valEl = document.getElementById('ds-key-new-value');
    const status = document.getElementById('ds-key-status');
    const name = (nameEl.value || '').trim();
    const value = (valEl.value || '').trim();
    if (!name || !value) {
        if (status) { status.textContent = 'Enter both a key name and value.'; status.style.color = 'red'; setTimeout(() => { status.textContent = ''; }, 3000); }
        return;
    }
    saveDataSourceKeys({ [name]: value });
    nameEl.value = '';
    valEl.value = '';
    renderDataSourceKeysSettings();
    if (status) { status.textContent = 'Key saved.'; status.style.color = 'green'; setTimeout(() => { status.textContent = ''; }, 2500); }
}

function saveApiKey() {
    const key = document.getElementById('GIBD-API-key').value.trim();
    const status = document.getElementById('api-key-status');
    if (!key) {
        status.textContent = 'Key is empty.';
        status.style.color = 'red';
        setTimeout(() => { status.textContent = ''; }, 3000);
        return;
    }
    // GIBD-only mode: reject non-GIBD keys so users don't accidentally enter
    // an OpenAI key. (OpenAI routing remains in the backend for future use.)
    if (!ALLOW_OPENAI_KEY && !/^gibd[-_]/i.test(key)) {
        status.textContent = 'Please enter a GIBD key (starts with "gibd-").';
        status.style.color = 'red';
        setTimeout(() => { status.textContent = ''; }, 4000);
        return;
    }
    // Both modes enabled: accept a GIBD key (gibd-...), an OpenAI key (sk-...),
    // or the "no-api" sentinel (identifies the session when every LLM call is
    // routed to a self-hosted open-source model server instead — see
    // Experiment 2's model server base URL setting). The backend routes by
    // prefix; warn early if it's none of these so the user doesn't save a
    // malformed key that fails on the first request.
    if (ALLOW_OPENAI_KEY && key !== 'no-api' && !/^(gibd[-_]|sk-)/i.test(key)) {
        status.textContent = 'Enter a GIBD key (starts with "gibd-"), an OpenAI key (starts with "sk-"), or "no-api" if you only use a self-hosted open-source model.';
        status.style.color = 'red';
        setTimeout(() => { status.textContent = ''; }, 4000);
        return;
    }
    const prev = localStorage.getItem('agm_openai_api_key');
    const next = key.replace(/\s/g, '');
    localStorage.setItem('agm_openai_api_key', next);
    // Key changed → reset the active chat and reload the sidebar so the
    // user sees conversations that belong to the new key, not the old one.
    if (prev !== next) {
        try { startNewChat(); } catch (e) { /* UI may not be ready yet */ }
        try { loadConversationList(); } catch (e) {}
    }
    refreshUserIdBadge();
    status.textContent = 'Key saved!';
    status.style.color = 'green';
    setTimeout(() => { status.textContent = ''; }, 3000);
}

function clearApiKey() {
    const status = document.getElementById('api-key-status');
    document.getElementById('GIBD-API-key').value = '';
    const hadKey = !!localStorage.getItem('agm_openai_api_key');
    localStorage.removeItem('agm_openai_api_key');
    // Tell the backend to clear the key from os.environ
    _originalFetch('/api/clear-key', { method: 'POST' }).catch(() => {});
    // Immediately reset the chat pane and sidebar so stale history from the
    // previous key isn't visible after it's been removed.
    if (hadKey) {
        try { startNewChat(); } catch (e) {}
        try { loadConversationList(); } catch (e) {}
    }
    refreshUserIdBadge();
    status.textContent = 'Key cleared!';
    status.style.color = 'orange';
    setTimeout(() => { status.textContent = ''; }, 3000);
}

function toggleApiKeyVisibility(btn) {
    const input = document.getElementById('GIBD-API-key');
    if (input.type === 'text') {
        input.type = 'password';
        btn.textContent = '👁';
    } else {
        input.type = 'text';
        btn.textContent = '👁';
    }
}

// Show the user_id the server derives from the saved key (sha256(key)[:16]).
// Goes through the wrapped fetch so the X-API-Key header is attached; hidden
// when there is no key or the server can't be reached.
async function refreshUserIdBadge() {
    const row = document.getElementById('api-key-user-id');
    const value = document.getElementById('api-key-user-id-value');
    if (!row || !value) return;
    if (!localStorage.getItem('agm_openai_api_key')) {
        row.style.display = 'none';
        value.textContent = '';
        return;
    }
    try {
        const resp = await fetch(`${API_BASE_URL}/api/whoami`);
        const data = await resp.json();
        if (resp.ok && data.success && data.user_id) {
            value.textContent = data.user_id;
            row.style.display = '';
            return;
        }
    } catch (e) { /* server down or key rejected: just don't show an id */ }
    row.style.display = 'none';
    value.textContent = '';
}

function copyUserId() {
    const value = document.getElementById('api-key-user-id-value');
    const status = document.getElementById('api-key-status');
    if (!value || !value.textContent) return;
    navigator.clipboard.writeText(value.textContent).then(() => {
        if (!status) return;
        status.textContent = 'ID copied';
        status.style.color = 'green';
        setTimeout(() => { status.textContent = ''; }, 2000);
    }).catch(() => {});
}

